def unlink_shared_movements(apps, _schema_editor):
    """Keep at most one row per movement without inventing money.

    A proven resolved row becomes the canonical one regardless of pk order.
    Identical observations on the same account become repeats; different,
    unresolved or foreign-account ones lose the movement link. If no row is
    proven resolved, every link is released. Audit entries and balances stay.
    """
    row_model = apps.get_model('users', 'BankStatementRow')
    upload_model = apps.get_model('users', 'BankStatementUpload')
    upload_accounts = dict(
        upload_model.objects.values_list('pk', 'account_id'),
    )
    resolved = {'new', 'linked', 'transferred', 'not_a_payment'}
    rows_by_movement = {}
    for row in (
        row_model.objects.filter(transaction__isnull=False)
        .order_by('pk')
        .iterator()
    ):
        rows_by_movement.setdefault(row.transaction_id, []).append(row)

    for rows in rows_by_movement.values():
        canonical = next(
            (row for row in rows if row.decision in resolved),
            None,
        )
        if canonical is None:
            row_model.objects.filter(
                pk__in=[row.pk for row in rows],
            ).update(
                transaction=None,
                decision='pending',
                decided_at=None,
                canonical_row=None,
            )
            continue
        canonical_account = upload_accounts.get(canonical.upload_id)
        for row in rows:
            if row.pk == canonical.pk:
                continue
            account_id = upload_accounts.get(row.upload_id)
            same_observation = (
                row.decision in resolved
                and account_id == canonical_account
                and row.transaction_type == canonical.transaction_type
                and row.amount == canonical.amount
                and row.transaction_date == canonical.transaction_date
            )
            if same_observation:
                row_model.objects.filter(pk=row.pk).update(
                    transaction=None,
                    decision='duplicate',
                    canonical_row_id=canonical.pk,
                )
            else:
                row_model.objects.filter(pk=row.pk).update(
                    transaction=None,
                    decision='pending',
                    decided_at=None,
                    canonical_row=None,
                )


